class Solution {
public:
    bool isConsecutive(vector<int>& nums) {
        unordered_set<int> s(nums.begin(), nums.end());
        if (s.size() != nums.size()) return false;
        int mn = *min_element(nums.begin(), nums.end());
        int mx = *max_element(nums.begin(), nums.end());
        return mx - mn == (int)nums.size() - 1;
    }
};

class Solution {
    public boolean isConsecutive(int[] nums) {
        Set<Integer> set = new HashSet<>();
        int min = Integer.MAX_VALUE, max = Integer.MIN_VALUE;
        for (int x : nums) {
            set.add(x);
            min = Math.min(min, x);
            max = Math.max(max, x);
        }
        return set.size() == nums.length && (max - min == nums.length - 1);
    }
}

/**
 * @param {number[]} nums
 * @return {boolean}
 */
var isConsecutive = function(nums) {
    const s = new Set(nums);
    if (s.size !== nums.length) return false;
    let mn = nums[0], mx = nums[0];
    for (const x of nums) {
        if (x < mn) mn = x;
        if (x > mx) mx = x;
    }
    return mx - mn === nums.length - 1;
};
